   "solution":"Правильный порядок: describe для событий, затем logs --previous — именно там осталась причина падения, потому что текущий контейнер живёт секунды. Поскольку три пода из четырёх работают на новой версии, дело скорее в конкретном поде или в зависимости, доступной не отовсюду. Первая гипотеза — новое значение CACHE_URL: адрес может не резолвиться или быть недоступен с узла, где размещён этот под. Вторая — нехватка памяти именно на этом узле, тогда в describe будет OOMKilled и код 137. Третья — liveness с коротким таймаутом, убивающий приложение до окончания старта. Различаются они по событиям и коду завершения. Параллельно с разбором стоит оценить откат: сервис работает частично, и если деградация заметна пользователям, возврат к прежней версии важнее скорости расследования. Удаление пода руками бесполезно: новый воспроизводит то же поведение, потому что причина в описании, а не в экземпляре.",
