   "solution":"Первое и единственное срочное действие — отозвать токен и выпустить новый. Токен был доступен публично 19 часов, поэтому считается скомпрометированным независимо от того, что с ним делали дальше. Удаление файла следующим коммитом не меняет ничего: значение осталось в истории и в каждом сделанном клоне. Закрытие репозитория тоже не помогает — копии уже могли быть получены. После отзыва надо посмотреть журнал платёжного провайдера: были ли обращения с этим токеном, с каких адресов, создавались ли платежи. Это определяет, ограничиваемся ли мы технической мерой или инцидент требует уведомления финансовой и юридической стороны. Чистка истории делается после, как уборка. Чтобы не повторилось, нужны две вещи: автоматическая проверка на секреты до коммита и вынос секретов в отдельное хранилище, чтобы файла с боевым значением рядом с кодом просто не существовало.",
