   "scenario":"Резервное копирование базы настроено год назад и отрабатывает каждую ночь без ошибок: в журнале ежедневно «backup completed», файлы лежат на том же сервере в каталоге /var/backups. Размер файла примерно совпадает с размером базы. Восстановление ни разу не проверяли. Руководство спрашивает, за какое время вы восстановите сервис при отказе диска и сколько данных потеряете.",
   "solution":"Честный ответ руководству: сейчас назвать эти цифры невозможно, потому что восстановление ни разу не выполнялось, и любая названная цифра будет выдумкой. Две проблемы видны сразу. Первая — способ: копирование файлов работающей базы без остановки записи даёт снимок, части которого относятся к разным моментам времени; такой файл может просто не открыться. Вторая — расположение: копия на том же сервере не защищает от отказа этого сервера, а именно этот сценарий и спрашивают. Начать надо с пробного восстановления на отдельной машине: оно либо подтвердит пригодность, либо покажет, что год копий бесполезен. Заодно даст реальное время восстановления. Дальше это переводится в разговор с бизнесом: сколько данных допустимо потерять и сколько может длиться простой. Из этих двух чисел уже следуют технические решения — частота копий, способ и место хранения. Обратный порядок, когда схему выбирают первой, приводит ровно к такой ситуации.",
