   "scenario":"Платформенная команда получает запрос на добавление четырёх узлов: кластер показывает 87% занятости, новые сервисы не размещаются и висят в Pending. При этом на панели потребления видно, что фактическая загрузка процессора по кластеру около 22%, памяти — около 30%. В кластере 40 сервисов от восьми команд. У большинства сервисов requests по памяти стоят 1 ГБ, у некоторых — 4 ГБ.",
   "solution":"Расхождение объясняется тем, что планировщик резервирует ресурсы по запросам, независимо от фактического потребления. Кластер занят обещаниями, а не работой. Новые узлы решат симптом и закрепят проблему: через полгода ситуация повторится в большем масштабе. Начать надо со сравнения запрошенного и фактического по каждому сервису и взять первую десятку самых расточительных — обычно они дают основную долю. Снижать запросы надо поэтапно и с наблюдением: резкое одинаковое сокращение приведёт к вытеснению подов и убийству по памяти, то есть к аварии на ровном месте. Совсем убирать requests нельзя: тогда планировщик потеряет основания для размещения, а сервисы — гарантии. На будущее нужна не разовая уборка, а правило: запросы обосновываются измерениями, и есть регулярная сверка запрошенного с фактическим. Полезно показать командам их собственные цифры — это работает лучше административных требований.",
