   "category":"Технический вопрос",
   "hint":"Симптом → метрики → зависимости → недавние изменения. Сначала уменьшить ущерб, потом искать причину.",
   "id":"ed-devops-001",
   "keywords":[
    "I'd check the metrics",
    "recent changes",
    "roll back"
   ],
   "level":2,
   "model_answer_en":"First I'd look at the metrics: latency, error rate and saturation, and I'd check whether it's all requests or only one endpoint. Then I'd check dependencies — database, queue, external APIs. In parallel I'd look at recent changes, because a deploy an hour ago is the most likely cause. If a change looks suspicious, I'd roll it back first and investigate after: reducing the impact comes before finding the root cause.",
   "model_answer_ru":"Сначала метрики: задержка, доля ошибок, загрузка ресурсов, и все ли запросы медленные или только один эндпоинт. Потом зависимости: база, очередь, внешние API. Параллельно — недавние изменения, потому что выкат час назад самая вероятная причина. Если изменение выглядит подозрительно, сначала откат, разбор потом: снизить ущерб важнее, чем найти первопричину.",
   "prompt_en":"A service is responding slowly. Walk me through your first steps.",
