   "level":3,
   "model_answer_en":"We had an outage of about twenty minutes: users couldn't log in. My role was to keep the timeline and check the metrics while a colleague rolled back the release. The impact was around two thousand failed logins. After the incident we wrote a blameless post-mortem, and the main change was an automatic check that blocks a deploy when the error rate goes up. What I learned is that the timeline is more useful than guesses: without it we couldn't tell which change caused it.",
   "model_answer_ru":"У нас был простой минут на двадцать: пользователи не могли войти. Я вёл(вела) хронологию и смотрел(а) метрики, пока коллега откатывал релиз. Пострадали примерно две тысячи попыток входа. После инцидента мы написали разбор без поиска виноватых, и главное изменение — автоматическая проверка, которая блокирует выкат при росте ошибок. Вывод: хронология полезнее догадок.",
   "prompt_en":"Describe an incident you took part in. What did you learn?",
   "prompt_ru":"Опишите инцидент, в котором вы участвовали. Какой вывод сделали?",
