   "category":"Технический вопрос",
   "hint":"Воспроизводимость, история изменений, ревью и восстановление после потери сервера.",
   "id":"ed-devops-003",
   "keywords":[
    "reproducible",
    "review",
    "restore"
   ],
   "level":3,
   "model_answer_en":"Because \"it works\" is not the same as \"we can rebuild it\". With infrastructure as code the environment is reproducible: the same file gives the same server. Changes go through review and have history, so we can see who changed what and roll it back. And if we lose a machine, we restore it in minutes instead of remembering what was installed there by hand.",
   "model_answer_ru":"Потому что «работает» и «можем собрать заново» — разные вещи. С инфраструктурой как кодом среда воспроизводима: один и тот же файл даёт один и тот же сервер. Изменения проходят ревью и имеют историю: видно, кто и что менял, и можно откатить. А если теряем машину, восстанавливаем за минуты, а не вспоминаем, что там ставили руками.",
   "prompt_en":"Why do we need infrastructure as code if everything already works?",
