   "summary":"Почти любая диагностика на Linux начинается одинаково: понять, что процесс делает, кто его запустил и что он написал в журнал. Три команды — systemctl status, journalctl -u и ps — закрывают большинство вопросов на собеседовании.",
   "title":"Процессы, службы и журнал",
   "topic_id":"linux-basics",
   "track_id":"devops-platform",
   "why_it_matters":"Junior-инженера почти наверняка попросят вслух разобрать ситуацию «служба не поднимается». Ответ проверяют не на знание флагов, а на порядок действий."
