   "summary":"Запрос проходит цепочку: DNS, TCP-соединение, TLS-рукопожатие, HTTP-ответ. Диагностика — это определить, на каком звене всё сломалось, а не гадать.",
   "title":"Сеть: от домена до ответа приложения",
