   "estimated_minutes":40,
   "example":"Сборка падает только в CI. Локально всё зелёное. Причина оказалась в кэше зависимостей: в CI он остался с прошлой недели и содержал старую версию библиотеки. Очистка кэша чинит симптом, но правильное решение — фиксировать версии зависимостей, чтобы результат не зависел от состояния кэша.",
