   "estimated_minutes":35,
   "example":"После выката пользователи периодически получают обрыв соединения. Причина: приложение запускается через shell-обёртку, SIGTERM приходит оболочке, а не процессу приложения. Через десять секунд ожидания приходит SIGKILL и рвёт живые запросы. Лечится запуском приложения главным процессом.",
