   "estimated_minutes":35,
   "example":"Образ приложения весит 1,2 ГБ, потому что собран в одну стадию: внутри остались компилятор, кэш пакетного менеджера и исходники. Многостадийная сборка с копированием только готового бинарника в финальную стадию уменьшает его до 80 МБ — при том же приложении.",
