   "estimated_minutes":40,
   "example":"В репозиторий случайно попал токен. Его удалили следующим коммитом, но он остался в истории и был доступен всем, у кого есть клон. Правильный порядок другой: сначала отозвать и выпустить новый токен, и только потом чистить историю.",
