   "estimated_minutes":40,
   "example":"Среднее время ответа 200 мс, все довольны. Перцентиль 99 показывает 8 секунд: каждый сотый запрос почти отваливается по таймауту. Именно эти пользователи и пишут в поддержку, а средняя метрика их не видит.",
