   "estimated_minutes":40,
   "example":"Релиз переименовал колонку в базе. Код выкатили, нашли ошибку, откатили — но старый код ищет колонку под прежним именем, которой уже нет. Сервис лежит уже из-за отката. Правильный путь: сначала добавить новую колонку и писать в обе, потом переключить чтение, и только следующим релизом удалить старую.",
