   "short_answer":"Ровно те, что нужны для выката именно этого сервиса, и не более. Отдельная учётная запись под задачу, а не общий токен на всё. Права выдаю на конкретное окружение и по возможности на время выполнения, а не бессрочно. Секреты беру из хранилища CI и слежу, чтобы они не попадали ни в лог, ни в аргументы команд — аргументы видно в списке процессов. Отдельно проверяю, что сборки из внешних вкладов не получают боевые секреты вообще: иначе любой присланный пул-реквест может их вынести.",
