   "estimated_minutes":40,
   "example":"Резервные копии делались год, каждый раз успешно. При первой реальной необходимости выяснилось, что копировался файл работающей базы без остановки записи: получался несогласованный снимок, который не открывается. Проверка восстановления обнаружила бы это в первый же день.",
