   "related_term_ids":[],
   "short_answer":"Называю конкретный случай без попытки его смягчить, потом коротко — что именно я сделал не так, потом главное: что изменил, чтобы это не повторилось. Например, я выкатил изменение в конце дня без проверки отката, и когда понадобилось откатиться, оказалось, что миграция это не позволяет. Восстановление заняло сильно дольше, чем должно было. После этого я стал делать миграции обратно совместимыми и проверять откат до выката, а не после. Мне важно показать не то, что я не ошибаюсь, а то, что после ошибки меняется процесс, а не только настроение.",
