   "estimated_minutes":25,
   "example":"Кластер показывал 85% занятости и требовал новых узлов. Реальное потребление было втрое ниже: половина сервисов просила по гигабайту памяти «на всякий случай». После приведения запросов к реальному потреблению узлы не понадобились.",
   "id":"lesson-cost-capacity",
