   "model_answer_short":"Pod — минимальная единица запуска: контейнеры с общей сетью и общей судьбой. Поды одноразовые, при пересоздании адрес меняется. Deployment описывает, сколько реплик какой версии должно работать, и сам управляет выкатом через смену наборов подов. Service даёт стабильную точку входа и балансирует трафик по подам, подходящим по меткам. Получается: Deployment следит, чтобы поды были, Service — чтобы до них можно было достучаться.",
