   "model_answer_short":"SLI — то, что измеряем, например доля успешных запросов. SLO — цель по этому показателю за период. Бюджет ошибок — оставшаяся часть допустимого неуспеха: при 99,9% за месяц это примерно 43 минуты. Смысл в том, что он превращает спор между скоростью и надёжностью в цифру: пока бюджет есть — катим смело, кончился — переключаемся на надёжность. И цель не может быть равна ста процентам: это обещание, которое нельзя выполнить.",
