   "model_answer_full":"Оценивается спокойный приоритет: пользователи важнее любопытства. Отдельно ценится готовность разбирать ложные срабатывания — большинство кандидатов про это не говорят, а именно шум быстрее всего убивает пользу от дежурств. Молчание во время аварии считается отдельной ошибкой.",
